    label(botR, DL[0] + 28, DL[1] + 12, '虚线：站着那台', 'demo-x-mut', 9.5);
    label(botR, DS[0] - 28, DS[1] + 4, '俯视朝向', 'demo-x-mut', 10, 'end');
    var yawTxt = label(botR, 610, 342, '', 'demo-x-ink', 11.5, 'middle');
