      var k = done ? ((Math.floor((now - ACC1) * cw.fps) % cw.n) + cw.n) % cw.n : Math.max(0, shown - 1);
      var fk = cw.frame(k), cam = camFor(cw.sheet, SC, 530, GY6, fk.root[0], fk.root[1]);
      h1T.put(fk.root, cam, k);
